import{n as e}from"./api-BY6iE3QA.js";var t={async getCustomers(t={}){return(await e.get(`/customers`,t)).data},async getCustomerById(t){return(await e.get(`/customers/${t}`)).data},async createCustomer(t){let n=await e.post(`/customers`,t);if(!n?.success)throw Error(n?.message||`客户创建失败`);return n.data},async parseCustomer(t,n){let r=await e.post(`/ai/parse-customer`,{text:t,...n?{channel:n}:{}});if(!r?.success||!r.data)throw Error(r?.message||`AI 解析失败`);return r.data},async updateCustomer(t,n){let r=await e.patch(`/customers/${t}`,n);if(!r?.success)throw Error(r?.message||`客户信息更新失败`);return r.data},async getAssignableUsers(){return(await e.get(`/customers/assignable-users`)).data||[]},async assignCustomer(t,n,r){return(await e.patch(`/customers/${t}/assign`,{assignedTo:n,assignmentReason:r})).data},async deleteCustomer(t){return e.delete(`/customers/${t}`)},async searchForESign(t,n=10){return((await e.get(`/customers/search`,{search:t,limit:n}))?.data||[]).map(e=>({id:e._id,name:e.name,phone:e.phone,idCard:e.idCardNumber,type:`customer`,source:`客户库`,address:e.address,createdAt:e.createdAt}))},async getStatistics(){return(await e.get(`/customers/statistics`)).data},async getFollowUps(t){return(await e.get(`/customers/${t}/follow-ups`)).data||[]},async createFollowUp(t,n){return(await e.post(`/customers/${t}/follow-ups`,n)).data||{type:``,content:``}},async releaseToPool(t,n){return(await e.post(`/customers/${t}/release-to-pool`,{reason:n})).data},async updateUrgency(t,n,r){return(await e.patch(`/customers/${t}/urgent`,{isUrgent:n,reason:r})).data},async updateStar(t,n){return(await e.patch(`/customers/${t}/star`,{starred:n})).data},async pushToAunties(t){return(await e.post(`/customers/${t}/push-to-aunties`)).data},async getMatchingCandidates(t,n=5){return(await e.get(`/customers/${t}/matching-candidates`,{limit:n})).data||[]}};export{t};